import { readFileSync } from "node:fs";

// The track list is shared with the client, so the two can never disagree.
// It is generated by scripts/build-tracks.mjs.
const FILE = new URL("../../client/src/data/tracks.json", import.meta.url);

export const tracks = JSON.parse(readFileSync(FILE, "utf8"));

const ids = new Set(tracks.map((track) => track.id));

export const isTrackId = (value) => typeof value === "string" && ids.has(value);
